# Pulumi ComponentResource: Service Stack

Here's a complete TypeScript implementation wrapping S3, RDS, and IAM into a reusable ComponentResource with dev/prod support.

## Structure

```
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── index.ts
└── components/
    └── applicationStack.ts
```

---

## `components/applicationStack.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";

interface ApplicationStackArgs {
  environment: string;
  bucketName: string;
  dbInstanceClass: string;
  dbAllocatedStorage: number;
  enableCrossRegionReplication?: boolean;
  replicationRegion?: string;
}

export interface ApplicationStackOutputs {
  bucketName: pulumi.Output<string>;
  bucketArn: pulumi.Output<string>;
  rdsEndpoint: pulumi.Output<string>;
  rdsPort: pulumi.Output<number>;
  iamRoleArn: pulumi.Output<string>;
  iamRoleName: pulumi.Output<string>;
  dbSecurityGroupId: pulumi.Output<string>;
}

/**
 * ApplicationStack ComponentResource
 * 
 * Wraps S3 bucket (versioned, encrypted), RDS PostgreSQL (deletion-protected),
 * and IAM role for service accounts. Supports dev/prod configuration.
 */
export class ApplicationStack extends pulumi.ComponentResource {
  public readonly bucketName: pulumi.Output<string>;
  public readonly bucketArn: pulumi.Output<string>;
  public readonly rdsEndpoint: pulumi.Output<string>;
  public readonly rdsPort: pulumi.Output<number>;
  public readonly iamRoleArn: pulumi.Output<string>;
  public readonly iamRoleName: pulumi.Output<string>;
  public readonly dbSecurityGroupId: pulumi.Output<string>;

  constructor(
    name: string,
    args: ApplicationStackArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:service:ApplicationStack", name, {}, opts);

    const parentOpts = { parent: this };

    // ========== S3 Bucket ==========
    const bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: args.bucketName,
        forceDestroy: false, // Prevent accidental deletion
        tags: {
          Environment: args.environment,
          ManagedBy: "Pulumi",
        },
      },
      parentOpts
    );

    // Versioning
    const versioning = new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: bucket.id,
        versioningConfiguration: {
          status: "Enabled",
        },
      },
      parentOpts
    );

    // Server-side encryption (AES-256)
    const encryption = new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-encryption`,
      {
        bucket: bucket.id,
        rules: [
          {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        ],
      },
      parentOpts
    );

    // Block public access
    const publicAccessBlock = new aws.s3.BucketPublicAccessBlock(
      `${name}-public-access-block`,
      {
        bucket: bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      parentOpts
    );

    // Cross-region replication (prod only)
    if (args.enableCrossRegionReplication && args.replicationRegion) {
      const replicationRole = new aws.iam.Role(
        `${name}-replication-role`,
        {
          assumeRolePolicy: pulumi.output({
            Version: "2012-10-17",
            Statement: [
              {
                Action: "sts:AssumeRole",
                Effect: "Allow",
                Principal: {
                  Service: "s3.amazonaws.com",
                },
              },
            ],
          }),
        },
        parentOpts
      );

      new aws.iam.RolePolicy(
        `${name}-replication-policy`,
        {
          role: replicationRole.id,
          policy: {
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Action: [
                  "s3:GetReplicationConfiguration",
                  "s3:ListBucket",
                ],
                Resource: bucket.arn,
              },
              {
                Effect: "Allow",
                Action: [
                  "s3:GetObjectVersionForReplication",
                  "s3:GetObjectVersionAcl",
                ],
                Resource: pulumi.interpolate`${bucket.arn}/*`,
              },
              {
                Effect: "Allow",
                Action: [
                  "s3:ReplicateObject",
                  "s3:ReplicateDelete",
                ],
                Resource: pulumi.interpolate`arn:aws:s3:::${args.bucketName}-replica/*`,
              },
            ],
          },
        },
        parentOpts
      );

      new aws.s3.BucketReplicationConfig(
        `${name}-replication`,
        {
          bucket: bucket.id,
          role: replicationRole.arn,
          rules: [
            {
              status: "Enabled",
              priority: 1,
              filter: {
                prefix: "",
              },
              destination: {
                bucket: pulumi.interpolate`arn:aws:s3:::${args.bucketName}-replica`,
                replicationTime: {
                  status: "Enabled",
                  time: {
                    minutes: 15,
                  },
                },
                metrics: {
                  status: "Enabled",
                  eventThreshold: {
                    minutes: 15,
                  },
                },
              },
            },
          ],
        },
        { ...parentOpts, dependsOn: [bucket, versioning] }
      );
    }

    // ========== RDS PostgreSQL Instance ==========
    const dbPasswordSecret = new random.RandomPassword(
      `${name}-db-password`,
      {
        length: 32,
        special: true,
      },
      parentOpts
    );

    // Database subnet group (assumes VPC + subnets exist or creates default)
    const dbSubnetGroup = new aws.rds.SubnetGroup(
      `${name}-db-subnet-group`,
      {
        subnetIds: (await aws.ec2.getSubnets({ filters: [] })).ids, // Use default VPC subnets
        tags: {
          Environment: args.environment,
        },
      },
      parentOpts
    );

    // Security group for RDS
    const dbSecurityGroup = new aws.ec2.SecurityGroup(
      `${name}-db-security-group`,
      {
        description: `Security group for ${name} RDS instance`,
        ingress: [
          {
            fromPort: 5432,
            toPort: 5432,
            protocol: "tcp",
            cidrBlocks: ["10.0.0.0/8"], // Restrict to VPC CIDR
          },
        ],
        egress: [
          {
            fromPort: 0,
            toPort: 0,
            protocol: "-1",
            cidrBlocks: ["0.0.0.0/0"],
          },
        ],
        tags: {
          Environment: args.environment,
        },
      },
      parentOpts
    );

    const rdsInstance = new aws.rds.Instance(
      `${name}-postgres`,
      {
        allocatedStorage: args.dbAllocatedStorage,
        storageType: "gp3",
        engine: "postgres",
        engineVersion: "14.7",
        instanceClass: args.dbInstanceClass,
        dbName: "appdb",
        username: "postgres",
        password: dbPasswordSecret.result,
        dbSubnetGroupName: dbSubnetGroup.name,
        vpcSecurityGroupIds: [dbSecurityGroup.id],
        publicly_accessible: false,
        skipFinalSnapshot: false,
        finalSnapshotIdentifier: pulumi.interpolate`${name}-final-snapshot-${Date.now()}`,
        backupRetentionPeriod: 7,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "mon:04:00-mon:05:00",
        deleteProtection: true,
        enableIAMDatabaseAuthentication: true,
        multiAz: args.environment === "prod",
        storageEncrypted: true,
        tags: {
          Environment: args.environment,
          ManagedBy: "Pulumi",
        },
      },
      parentOpts
    );

    // ========== IAM Role for Service Accounts ==========
    const serviceRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        assumeRolePolicy: pulumi.output({
          Version: "2012-10-17",
          Statement: [
            {
              Action: "sts:AssumeRole",
              Effect: "Allow",
              Principal: {
                AWS: `arn:aws:iam::${aws.getCallerIdentity({}).accountId}:root`, // Replace with IRSA principal in prod
              },
            },
          ],
        }),
        tags: {
          Environment: args.environment,
        },
      },
      parentOpts
    );

    // S3 bucket policy for service role
    const s3Policy = new aws.iam.RolePolicy(
      `${name}-s3-policy`,
      {
        role: serviceRole.id,
        policy: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Action: [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject",
                "s3:ListBucket",
                "s3:GetObjectVersion",
              ],
              Resource: [
                bucket.arn,
                pulumi.interpolate`${bucket.arn}/*`,
              ],
            },
          ],
        },
      },
      parentOpts
    );

    // RDS policy for service role
    const rdsPolicy = new aws.iam.RolePolicy(
      `${name}-rds-policy`,
      {
        role: serviceRole.id,
        policy: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Action: [
                "rds-db:connect",
              ],
              Resource: pulumi.interpolate`arn:aws:rds:${aws.getRegion().name}:${aws.getCallerIdentity().accountId}:db:${rdsInstance.identifier}`,
            },
          ],
        },
      },
      parentOpts
    );

    // ========== Outputs ==========
    this.bucketName = bucket.bucket;
    this.bucketArn = bucket.arn;
    this.rdsEndpoint = rdsInstance.endpoint;
    this.rdsPort = rdsInstance.port;
    this.iamRoleArn = serviceRole.arn;
    this.iamRoleName = serviceRole.name;
    this.dbSecurityGroupId = dbSecurityGroup.id;

    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucketArn,
      rdsEndpoint: this.rdsEndpoint,
      rdsPort: this.rdsPort,
      iamRoleArn: this.iamRoleArn,
      iamRoleName: this.iamRoleName,
      dbSecurityGroupId: this.dbSecurityGroupId,
    });
  }
}
```

