## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ApplicationStack } from "./components/applicationStack";

const config = new pulumi.Config();
const environment = pulumi.getStack();

// Read environment-specific config
const bucketNameBase = config.require("bucketNameBase");
const dbInstanceClass = config.require("dbInstanceClass");
const dbAllocatedStorage = config.getNumber("dbAllocatedStorage") || 20;
const enableCrossRegionReplication = config.getBoolean("enableCrossRegionReplication") || false;

const appStack = new ApplicationStack(`app-${environment}`, {
  environment,
  bucketName: `${bucketNameBase}-${environment}-${Date.now()}`,
  dbInstanceClass,
  dbAllocatedStorage,
  enableCrossRegionReplication,
  replicationRegion: "us-west-2",
});

// Export stack outputs
export const bucketName = appStack.bucketName;
export const bucketArn = appStack.bucketArn;
export const rdsEndpoint = appStack.rdsEndpoint;
export const rdsPort = appStack.rdsPort;
export const serviceRoleArn = appStack.iamRoleArn;
export const serviceRoleName = appStack.iamRoleName;
export const dbSecurityGroupId = appStack.dbSecurityGroupId;
```

